// @generated by:gauntlet run:godseye-local-jobs
import { randomUUID } from "node:crypto";
import { CONTROL_API_HEADER, CONTROL_API_VERSION, JobsOverview } from "@godseye/contracts";
import { InfrastructureEngine } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../apps/control-api/src/app.js";
import { loadConfiguration } from "../apps/control-api/src/config.js";
import { createControlClient } from "../packages/control-client/src/index.js";
import { owner, projectInput } from "./helpers.js";
import { HandlerFixture } from "./jobs-helpers.js";
import { type OwnerAuthFixture, ownerAuthFixture } from "./owner-auth-fixture.js";

describe("strict owner jobs HTTP and typed client", () => {
  let fixture: OwnerAuthFixture;
  let headers: Headers;
  const appFor = (infrastructure: InfrastructureEngine) =>
    createApp(
      fixture.core,
      loadConfiguration({ GODSEYE_MODE: "local" }),
      fixture.identity,
      infrastructure.foundation,
      undefined,
      infrastructure,
    );
  beforeEach(async () => {
    fixture = await ownerAuthFixture();
    headers = (await fixture.session()).headers;
    headers.set(CONTROL_API_HEADER, CONTROL_API_VERSION);
  });
  afterEach(async () => {
    await fixture.close();
  });
  const clientFor = (app: ReturnType<typeof createApp>) =>
    createControlClient({
      baseUrl: `${fixture.origin}/api/v1`,
      headers,
      fetch: async (target, init) => app.request(new Request(target, init)),
    });
  async function cell() {
    const project = await fixture.core.createProject(owner, projectInput, randomUUID());
    const environment = project.environments.find((item) => item.kind === "development");
    if (!environment) throw new Error("Jobs HTTP environment missing");
    return { project, environment };
  }
  const definitionInput = (scope: Awaited<ReturnType<typeof cell>>, name = "http-job") => ({
    projectId: scope.project.id,
    environmentId: scope.environment.id,
    expectedEnvironmentRevision: scope.environment.revision,
    name,
    handler: "fixture.work",
    trigger: { kind: "manual" as const },
    effectPolicy: "idempotent" as const,
    limits: { maxConcurrent: 1, maxAttempts: 1, timeoutSeconds: 30, retentionDays: 7 },
  });

  it("authenticates every owner jobs route before interpreting caller bodies", async () => {
    const app = appFor(new InfrastructureEngine(fixture.store));
    for (const [method, path] of [
      ["GET", "/jobs"],
      ["POST", "/jobs/definitions"],
      ["POST", `/jobs/definitions/${randomUUID()}/pause`],
      ["POST", `/jobs/definitions/${randomUUID()}/resume`],
      ["POST", `/jobs/definitions/${randomUUID()}/trigger`],
      ["POST", `/jobs/runs/${randomUUID()}/cancel`],
      ["POST", `/jobs/runs/${randomUUID()}/reconcile`],
      ["POST", `/jobs/outbox/${randomUUID()}/reconcile`],
    ] as const) {
      const response = await app.request(new URL(`/api/v1${path}`, fixture.origin), {
        method,
        headers: fixture.headers(),
        ...(method === "GET" ? {} : { body: "{}" }),
      });
      expect(response.status).toBe(401);
    }
  });
  it("reports the default engine as unconfigured and refuses to trigger work", async () => {
    const app = appFor(new InfrastructureEngine(fixture.store));
    const client = clientFor(app);
    const scope = await cell();
    const definition = await client.registerJobDefinition(definitionInput(scope), randomUUID());
    const overview = JobsOverview.parse(await client.jobsOverview());
    expect(overview.engine.state).toBe("unconfigured");
    expect(overview.definitions.map((item) => item.id)).toEqual([definition.id]);
    const refused = await app.request(
      new URL(`/api/v1/jobs/definitions/${definition.id}/trigger`, fixture.origin),
      {
        method: "POST",
        headers: new Headers({ ...Object.fromEntries(headers), "idempotency-key": randomUUID() }),
        body: JSON.stringify({ expectedRevision: 0, dedupeKey: "http-unconfigured" }),
      },
    );
    expect(refused.status).toBe(503);
  });
  it("drives a fixture-backed lifecycle through the typed client", async () => {
    const handler = new HandlerFixture();
    const infrastructure = new InfrastructureEngine(fixture.store, {
      jobs: { handlers: new Map([["fixture.work", handler]]), timeoutMs: () => 50 },
    });
    const client = clientFor(appFor(infrastructure));
    const scope = await cell();
    await infrastructure.foundation.configureBudget(
      owner,
      scope.project.id,
      { limitMicros: 0, expectedRevision: 0 },
      randomUUID(),
    );
    const definition = await client.registerJobDefinition(definitionInput(scope), randomUUID());
    const run = await client.triggerJob(
      definition.id,
      { expectedRevision: definition.revision, dedupeKey: "http-trigger-1" },
      randomUUID(),
    );
    expect(run.state).toBe("queued");
    await infrastructure.jobs.tick();
    await infrastructure.foundation.tick("http-worker");
    await infrastructure.jobs.tick();
    const overview = await client.jobsOverview();
    expect(overview.engine.state).toBe("local_fixture");
    expect(overview.runs[0]).toMatchObject({ id: run.id, state: "succeeded" });
    const paused = await client.pauseJobDefinition(definition.id, 0, randomUUID());
    expect(paused.paused).toBe(true);
    const resumed = await client.resumeJobDefinition(definition.id, paused.revision, randomUUID());
    expect(resumed.paused).toBe(false);
    const second = await client.triggerJob(
      definition.id,
      { expectedRevision: resumed.revision, dedupeKey: "http-trigger-2" },
      randomUUID(),
    );
    const cancelled = await client.cancelJobRun(second.id, "operator abort", randomUUID());
    expect(cancelled.state).toBe("cancelled");
  });
  it("reconciles an unknown protected run through the typed client without re-executing it", async () => {
    const handler = new HandlerFixture();
    handler.script = async () => ({ status: "unknown" });
    handler.probe = async () => ({ status: "succeeded", evidenceRef: "observed:receipt-1" });
    const infrastructure = new InfrastructureEngine(fixture.store, {
      jobs: { handlers: new Map([["fixture.work", handler]]), timeoutMs: () => 50 },
    });
    const client = clientFor(appFor(infrastructure));
    const scope = await cell();
    await infrastructure.foundation.configureBudget(
      owner,
      scope.project.id,
      { limitMicros: 0, expectedRevision: 0 },
      randomUUID(),
    );
    const definition = await client.registerJobDefinition(
      { ...definitionInput(scope, "http-protected"), effectPolicy: "protected" },
      randomUUID(),
    );
    const run = await client.triggerJob(
      definition.id,
      { expectedRevision: definition.revision, dedupeKey: "http-protected-1" },
      randomUUID(),
    );
    await infrastructure.jobs.tick();
    await infrastructure.foundation.tick("http-worker");
    await infrastructure.jobs.tick();
    expect((await client.jobsOverview()).runs[0]).toMatchObject({ id: run.id, state: "unknown" });
    const input = {
      expectedState: "unknown" as const,
      resolution: "probe_read_only" as const,
      evidenceRef: "owner:ticket-0042",
    };
    await expect(
      client.reconcileJobRun(run.id, { ...input, expectedState: "reconciling" }, randomUUID()),
    ).rejects.toBeInstanceOf(Error);
    const reconciled = await client.reconcileJobRun(run.id, input, randomUUID());
    expect(reconciled.state).toBe("succeeded");
    expect(handler.calls).toHaveLength(1);
  });
  it("refuses reconciliation of a run that is not protected", async () => {
    const handler = new HandlerFixture();
    const infrastructure = new InfrastructureEngine(fixture.store, {
      jobs: { handlers: new Map([["fixture.work", handler]]), timeoutMs: () => 50 },
    });
    const client = clientFor(appFor(infrastructure));
    const scope = await cell();
    const definition = await client.registerJobDefinition(
      definitionInput(scope, "http-idempotent"),
      randomUUID(),
    );
    const run = await client.triggerJob(
      definition.id,
      { expectedRevision: definition.revision, dedupeKey: "http-idempotent-1" },
      randomUUID(),
    );
    await expect(
      client.reconcileJobRun(
        run.id,
        {
          expectedState: "unknown",
          resolution: "probe_read_only",
          evidenceRef: "owner:ticket-0043",
        },
        randomUUID(),
      ),
    ).rejects.toBeInstanceOf(Error);
  });
});
